var DATA = {"mode": "furmark", "res": "1920x1080", "msaa": 4};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="furmark"){
  show("Test","furry donut 3D render");
  show("Resolution",DATA.res);
  show("MSAA",DATA.msaa+"x");
  show("Why it works","maximum sustained GPU power draw");
}else if(m==="prime_modes"){
  console.log("Torture test modes:");
  DATA.modes.forEach(function(x){console.log("  "+x);});
}else if(m==="mersenne"){
  var p=DATA.p,M=Math.pow(2,p)-1,s=4,i;
  for(i=0;i<p-2;i++){s=(s*s-2)%M;}
  show("Testing","2^"+p+" - 1 = "+M);
  show("Lucas-Lehmer",s===0?"PRIME - a Mersenne prime":"composite");
  show("Note","the real test Prime95 runs, at tiny scale");
}else if(m==="workers"){
  show("Workers",DATA.n);
  show("Rule","one worker per thread by default");
  show("Each worker","an independent FFT workload");
}else if(m==="fft"){
  show("FFT size",DATA.fft+"K");
  show("Stresses most",DATA.what);
}else if(m==="blend"){
  show("Blend test","CPU and RAM together");
  show("RAM exercised",DATA.ram+" GB");
}else if(m==="temps"){
  show("CPU temp",DATA.cpu+" C");
  show("GPU temp",DATA.gpu+" C");
  show("Verdict",(DATA.cpu<90&&DATA.gpu<85)?"PASS":"FAIL - cooling inadequate");
}else if(m==="score"){
  show("FurMark score",DATA.score);
  show("Average FPS",DATA.fps);
  show("At",DATA.res);
}else if(m==="safety"){
  console.log("Safety rules:");
  DATA.rules.forEach(function(r,i){console.log("  "+(i+1)+". "+r);});
}else if(m==="cmdline"){
  show("Command",DATA.cmd);
  show("Use","scripted burn-in without the GUI");
}else if(m==="graph"){
  show("FurMark graph","live GPU temperature curve");
  show("Prime95 view","per-worker iteration times");
}else if(m==="pick"){
  show("GPU only","FurMark");
  show("CPU only","Prime95 small FFTs");
  show("CPU + RAM","Prime95 blend");
  show("Everything","both at once - maximum PSU load");
}else if(m==="psu"){
  show("CPU draw",DATA.cpu+" W");
  show("GPU draw",DATA.gpu+" W");
  show("Combined vs PSU",(DATA.cpu+DATA.gpu)+" W of "+DATA.psu+" W");
  show("Headroom",(DATA.psu-DATA.cpu-DATA.gpu)+" W");
}else if(m==="history"){
  show("Prime95","Mersenne prime hunting for GIMPS since 1996");
  show("FurMark","Geeks3D's furry-donut GPU burner");
}else if(m==="workflow"){
  console.log("Stability workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
